INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_03','V928','阮明',3,'校外社交、兼职有哪些需要格外留意的陷阱？','xiào wài shè jiāo、 jiān zhí yǒu nǎ xiē xū yào gé wài liú yì de xiàn jǐng？','Vậy giao tiếp bên ngoài, làm thêm thì có những cạm bẫy nào cần đặc biệt chú ý ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_04','V928','学长',4,'陌生线下兼职、陌生网友单独见面一定要选公共场所。','mò shēng xiàn xià jiān zhí、 mò shēng wǎng yǒu dān dú jiàn miàn yí dìng yào xuǎn gōng gòng chǎng suǒ。','Việc làm thêm gặp ngoài đời với người lạ hay hẹn gặp bạn quen qua mạng nhất định phải chọn nơi công cộng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_05','V928','阮明',5,'和本国、中国同学相处，有什么容易产生误会的文化细节？','hé běn guó、 zhōng guó tóng xué xiāng chǔ， yǒu shén me róng yì chǎn shēng wù huì de wén huà xì jié？','Khi giao lưu với bạn cùng nước và bạn Trung Quốc, có chi tiết văn hóa nào dễ gây hiểu lầm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_06','V928','学长',6,'送礼、借钱、作息边界提前沟通清楚，能减少大部分矛盾。','sòng lǐ、 jiè qián、 zuò xī biān jiè tí qián gōu tōng qīng chǔ， néng jiǎn shǎo dà bù fèn máo dùn。','Chuyện tặng quà, mượn tiền, giờ giấc sinh hoạt nên trao đổi rõ trước, sẽ giảm được phần lớn mâu thuẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_07','V928','阮明',7,'记下您的建议，避免社交踩坑吃亏。','jì xià nín de jiàn yì， bì miǎn shè jiāo cǎi kēng chī kuī。','Em ghi nhớ lời khuyên của anh rồi, để tránh vấp phải rắc rối trong giao tiếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT929','SXH5','班级集体短途出游，主动分担采购零食、清点人数的小事',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V929','SIT929','P1','suon_se','tuy_y',NULL,'班级集体活动大家主动分担琐碎工作，是体现集体意识、快速拉近同学关系的社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_01','V929','阮明',1,'班长，出游采购零食、清点人数的活我可以帮忙分担。','bān zhǎng， chū yóu cǎi gòu líng shí、 qīng diǎn rén shù de huó wǒ kě yǐ bāng máng fēn dān。','Lớp trưởng ơi, việc mua đồ ăn vặt với điểm danh số người cho chuyến đi chơi thì để mình giúp một tay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_02','V929','班长',2,'太好了，全班三十人，清点人数很耗费精力。','tài hǎo le， quán bān sān shí rén， qīng diǎn rén shù hěn hào fèi jīng lì。','Tốt quá, cả lớp ba mươi người, điểm danh cũng tốn sức lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_03','V929','阮明',3,'我统计所有人忌口，采购零食避开辣椒、坚果过敏原。','wǒ tǒng jì suǒ yǒu rén jì kǒu， cǎi gòu líng shí bì kāi là jiāo、 jiān guǒ guò mǐn yuán。','Mình sẽ thống kê xem ai kiêng món gì, mua đồ ăn vặt tránh ớt với các loại hạt dễ gây dị ứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_04','V929','班长',4,'采购费用全班AA，我把预算清单发到班级群公示。','cǎi gòu fèi yòng quán bān AA， wǒ bǎ yù suàn qīng dān fā dào bān jí qún gōng shì。','Chi phí mua đồ chia đều cả lớp nhé, mình sẽ đăng bảng dự toán lên nhóm lớp công khai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_05','V929','阮明',5,'集合时我站队伍末尾，确保没有人掉队遗漏。','jí hé shí wǒ zhàn duì wǔ mò wěi， què bǎo méi yǒu rén diào duì yí lòu。','Lúc tập trung mình sẽ đứng cuối hàng, đảm bảo không ai bị lạc hay bỏ sót.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_06','V929','班长',6,'有你分担工作，集体出游组织轻松很多。','yǒu nǐ fēn dān gōng zuò， jí tǐ chū yóu zǔ zhī qīng sōng hěn duō。','Có cậu chia sẻ công việc, tổ chức đi chơi tập thể nhẹ nhàng hơn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_07','V929','阮明',7,'班级集体活动大家互相搭把手，出行更顺利。','bān jí jí tǐ huó dòng dà jiā hù xiāng dā bǎ shǒu， chū xíng gèng shùn lì。','Hoạt động tập thể của lớp mà mọi người cùng giúp đỡ nhau thì chuyến đi sẽ suôn sẻ hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT930','SXH5','社团线下团建，协调时间冲突无法到场，提前说明并托人转达祝福',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V930','SIT930','P1','that_bai_nhe','ban_chinh_thuc',NULL,'社团团建无法到场需要提前说明缘由，准备小礼物托人转交表达心意，体现重视社团集体、不失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_01','V930','阮明',1,'学姐，团建当天我有汉语等级考试，没办法到场参与活动。','xué jiě， tuán jiàn dàng tiān wǒ yǒu hàn yǔ děng jí kǎo shì， méi bàn fǎ dào chǎng cān yù huó dòng。','Chị ơi, hôm team building em có kỳ thi năng lực tiếng Trung nên không thể tham gia được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_02','V930','学姐',2,'团建一年只有一次，错过这次集体聚餐有点可惜。','tuán jiàn yī nián zhǐ yǒu yī cì， cuò guò zhè cì jí tǐ jù cān yǒu diǎn kě xī。','Team building một năm chỉ có một lần, bỏ lỡ bữa tiệc tập thể này cũng hơi tiếc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_03','V930','阮明',3,'我提前买好社团小伴手礼，托到场的同学分给大家，转达我的祝福。','wǒ tí qián mǎi hǎo shè tuán xiǎo bàn shǒu lǐ， tuō dào chǎng de tóng xué fēn gěi dà jiā， zhuǎn dá wǒ de zhù fú。','Em đã mua sẵn chút quà nhỏ của câu lạc bộ, nhờ bạn nào có mặt hôm đó chia cho mọi người, gửi lời chúc của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_04','V930','学姐',4,'心意我们收下，考试优先，学业比团建重要。','xīn yì wǒ men shōu xià， kǎo shì yōu xiān， xué yè bǐ tuán jiàn zhòng yào。','Tấm lòng của em bọn chị nhận rồi, thi cử ưu tiên trước, học hành quan trọng hơn team building mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_05','V930','阮明',5,'下次社团小型聚会我一定到场，补上这次缺席。','xià cì shè tuán xiǎo xíng jù huì wǒ yí dìng dào chǎng， bǔ shàng zhè cì quē xí。','Lần tụ họp nhỏ tiếp theo của câu lạc bộ em nhất định sẽ có mặt, bù lại lần vắng này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_06','V930','学姐',6,'祝你等级考试顺利，不用惦记团建的事。','zhù nǐ děng jí kǎo shì shùn lì， bù yòng diàn jì tuán jiàn de shì。','Chúc em thi năng lực suôn sẻ nhé, đừng bận tâm chuyện team building nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_07','V930','阮明',7,'十分抱歉错过集体团建，麻烦学姐代为向大家致歉。','shí fēn bào qiàn cuò guò jí tǐ tuán jiàn， má fán xué jiě dài wéi xiàng dà jiā zhì qiàn。','Em thật sự rất xin lỗi vì lỡ hẹn team building tập thể, phiền chị thay em xin lỗi mọi người ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT931','SXH6','朋友频繁借大额现金，委婉说明自身开销，拒绝频繁借钱',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V931','SIT931','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友之间小额应急可互相周转，频繁大额借钱会明确划定边界委婉拒绝，避免金钱损耗友情。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_01','V931','阮明',1,'你最近频繁借大额生活费，我每月家里汇款固定，结余不多。','nǐ zuì jìn pín fán jiè dà é shēng huó fèi， wǒ měi yuè jiā lǐ huì kuǎn gù dìng， jié yú bù duō。','Dạo này cậu cứ mượn tiền sinh hoạt số lượng lớn hoài, mỗi tháng nhà gửi cho mình cố định, dư ra chẳng bao nhiêu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_02','V931','小杨',2,'我临时手头周转不开，才一次次找你借钱应急。','wǒ lín shí shǒu tóu zhōu zhuǎn bù kāi， cái yī cì cì zhǎo nǐ jiè qián yìng jí。','Mình nhất thời xoay không kịp nên mới phải tìm cậu mượn tạm nhiều lần vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_03','V931','阮明',3,'小额应急可以帮忙，但大额资金我自身学费、教材开销压力大嘛。','xiǎo é yìng jí kě yǐ bāng máng， dàn dà é zī jīn wǒ zì shēn xué fèi、 jiào cái kāi xiāo yā lì dà ma。','Số tiền nhỏ để ứng cấp thì mình giúp được, nhưng khoản lớn thì bản thân mình còn áp lực học phí, tiền sách vở nữa mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_04','V931','小杨',4,'明白你的难处，之后我尽量自己规划开支不再频繁借钱。','míng bái nǐ de nán chǔ， zhī hòu wǒ jǐn liàng zì jǐ guī huà kāi zhī bù zài pín fán jiè qián。','Mình hiểu khó khăn của cậu rồi, sau này mình sẽ cố tự lên kế hoạch chi tiêu, không mượn nhiều nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_05','V931','阮明',5,'如果是紧急看病这种急事我一定尽力帮忙，日常消费没法长期出借。','rú guǒ shì jǐn jí kàn bìng zhè zhǒng jí shì wǒ yí dìng jìn lì bāng máng， rì cháng xiāo fèi méi fǎ cháng qī chū jiè。','Nếu là việc gấp như đi khám bệnh thì mình nhất định sẽ cố hết sức giúp, còn chi tiêu hàng ngày thì mình không thể cho mượn dài hạn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_06','V931','小杨',6,'我理解你的边界，不会再频繁向你借大额钱款。','wǒ lǐ jiě nǐ de biān jiè， bú huì zài pín fán xiàng nǐ jiè dà é qián kuǎn。','Mình hiểu giới hạn của cậu rồi, sẽ không mượn khoản lớn từ cậu thường xuyên nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_07','V931','阮明',7,'我们维持轻松的朋友关系，不用因为金钱产生隔阂。','wǒ men wéi chí qīng sōng de péng yǒu guān xì， bù yòng yīn wèi jīn qián chǎn shēng gé hé。','Chúng ta cứ giữ tình bạn thoải mái vậy thôi, đừng để chuyện tiền bạc làm sứt mẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT932','SXH6','他人强行推销商品、邀约兼职，礼貌拉开距离明确拒绝',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V932','SIT932','P1','suon_se','ban_chinh_thuc',NULL,'校园内推销、兼职邀约十分常见，礼貌温和但态度明确拒绝，对方不会持续纠缠。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_01','V932','阮明',1,'不好意思，我没有购买护肤品、参与兼职的打算。','bù hǎo yì sī， wǒ méi yǒu gòu mǎi hù fū pǐn、 cān yù jiān zhí de dǎ suàn。','Xin lỗi, em không có ý định mua mỹ phẩm hay tham gia làm thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_02','V932','推销人员',2,'这款产品留学生用很合适，兼职还能赚取生活费。','zhè kuǎn chǎn pǐn liú xué shēng yòng hěn hé shì， jiān zhí hái néng zhuàn qǔ shēng huó fèi。','Sản phẩm này rất hợp với du học sinh, làm thêm còn kiếm thêm tiền sinh hoạt được nữa đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_03','V932','阮明',3,'我课余全部用来复习汉语考试，没有时间做副业兼职嘛。','wǒ kè yú quán bù yòng lái fù xí hàn yǔ kǎo shì， méi yǒu shí jiān zuò fù yè jiān zhí ma。','Em dành hết thời gian ngoài giờ học để ôn thi tiếng Trung, không có thời gian làm thêm việc tay trái đâu ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_04','V932','推销人员',4,'耽误五分钟简单了解一下，不会占用你太久时间。','dān wù wǔ fēn zhōng jiǎn dān liǎo jiě yī xià， bú huì zhàn yòng nǐ tài jiǔ shí jiān。','Chỉ mất năm phút tìm hiểu sơ qua thôi, sẽ không chiếm nhiều thời gian của em đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_05','V932','阮明',5,'实在没有需求，我要赶回图书馆自习，先失陪了。','shí zài méi yǒu xū qiú， wǒ yào gǎn huí tú shū guǎn zì xí， xiān shī péi le。','Em thật sự không có nhu cầu, em phải chạy về thư viện tự học rồi, xin phép em đi trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_06','V932','推销人员',6,'好吧，不打扰你学习，有需要再联系我。','hǎo ba， bù dǎ rǎo nǐ xué xí， yǒu xū yào zài lián xì wǒ。','Thôi được, vậy không làm phiền em học nữa, khi nào cần thì liên hệ lại với anh nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_07','V932','阮明',7,'感谢介绍，我确实没有相关需求。','gǎn xiè jiè shào， wǒ què shí méi yǒu xiāng guān xū qiú。','Cảm ơn anh đã giới thiệu, nhưng em thực sự không có nhu cầu này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT933','SXH6','很久没联系的老友，主动发消息分享日常、维系友谊',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V933','SIT933','P1','suon_se','tuy_y',NULL,'国内友情不会因为许久不联络直接变淡，主动分享日常、约定线上聊天是维系远距离友谊常用方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_01','V933','阮明',1,'好久不见，最近刷到你朋友圈，想起之前我们一起打球的日子。','hǎo jiǔ bú jiàn， zuì jìn shuā dào nǐ péng yǒu quān， xiǎng qǐ zhī qián wǒ men yì qǐ dǎ qiú de rì zi。','Lâu rồi không gặp, lúc nãy lướt thấy story cậu, tự nhiên nhớ lại hồi mình hay đi đánh bóng chung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_02','V933','阿凯',2,'确实很久没聊天，你在中国留学生活还适应吗？','què shí hěn jiǔ méi liáo tiān， nǐ zài zhōng guó liú xué shēng huó hái shì yìng ma？','Đúng là lâu lắm rồi không trò chuyện, cuộc sống du học ở Trung Quốc của cậu ổn chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_03','V933','阮明',3,'一切顺利，汉语进步不少，拍了很多校园风景照片。','yī qiè shùn lì， hàn yǔ jìn bù bù shǎo， pāi le hěn duō xiào yuán fēng jǐng zhào piān。','Mọi thứ đều suôn sẻ, tiếng Trung tiến bộ kha khá, còn chụp được cả đống ảnh phong cảnh trường nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_04','V933','阿凯',4,'有空周末线上视频，聊聊各自近期的学习生活。','yǒu kòng zhōu mò xiàn shàng shì pín， liáo liáo gè zì jìn qī de xué xí shēng huó。','Rảnh thì cuối tuần mình gọi video online nhé, kể cho nhau nghe chuyện học hành gần đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_05','V933','阮明',5,'这周日晚上七点我有空，准时线上跟你聊天叙旧。','zhè zhōu rì wǎn shàng qī diǎn wǒ yǒu kòng， zhǔn shí xiàn shàng gēn nǐ liáo tiān xù jiù。','Tối chủ nhật này bảy giờ mình rảnh, đúng giờ đó lên online tám chuyện với cậu luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_06','V933','阿凯',6,'好，到时候线上碰面，多聊聊近况。','hǎo， dào shí hòu xiàn shàng pèng miàn， duō liáo liáo jìn kuàng。','Ok, vậy hẹn online gặp nhau, tám nhiều chuyện gần đây nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_07','V933','阮明',7,'许久不联系也要偶尔分享日常，别慢慢疏远。','xǔ jiǔ bù lián xì yě yào ǒu ěr fēn xiǎng rì cháng， bié màn màn shū yuǎn。','Lâu không liên lạc thì cũng phải thỉnh thoảng chia sẻ chuyện thường ngày, đừng để xa nhau dần nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT934','SXH6','朋友过度打探家庭、生活费隐私，温和转移话题守住边界',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V934','SIT934','P1','twist','tuy_y',NULL,'国内社交不会过度追问收入、家庭条件等隐私，若对方过度打探，温和转移话题是委婉守住边界的礼貌方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_01','V934','阮明',1,'生活费够用就行，我们换个话题聊聊周末去哪游玩吧。','shēng huó fèi gòu yòng jiù xíng， wǒ men huàn gè huà tí liáo liáo zhōu mò qù nǎ yóu wán ba。','Tiền sinh hoạt đủ xài là được rồi, mình đổi chủ đề đi, bàn xem cuối tuần đi chơi đâu nè.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_02','V934','小周',2,'只是好奇问问，你家里每月给你汇多少越南盾？','zhǐ shì hào qí wèn wèn， nǐ jiā lǐ měi yuè gěi nǐ huì duō shǎo yuè nán dùn？','Tò mò hỏi vậy thôi, mỗi tháng nhà cậu gửi cho cậu bao nhiêu tiền Việt vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_03','V934','阮明',3,'各国家庭收支习惯不一样，不太习惯细说家庭财务情况嘛。','gè guó jiā tíng shōu zhī xí guàn bù yí yàng， bù tài xí guàn xì shuō jiā tíng cái wù qíng kuàng ma。','Thói quen thu chi mỗi gia đình mỗi nước khác nhau, mình cũng không quen kể chi tiết chuyện tiền bạc trong nhà lắm.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_04','V934','小周',4,'抱歉，我不知道这是你的隐私，我之后不会再追问这类问题。','bào qiàn， wǒ bù zhī dào zhè shì nǐ de yǐn sī， wǒ zhī hòu bú huì zài zhuī wèn zhè lèi wèn tí。','Xin lỗi nha, mình không biết đây là chuyện riêng tư của cậu, sau này mình sẽ không hỏi mấy chuyện này nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_05','V934','阮明',5,'没关系，我们聊聊校园文艺晚会的节目更有意思。','méi guān xì， wǒ men liáo liáo xiào yuán wén yì wǎn huì de jié mù gèng yǒu yì si。','Không sao đâu, mình nói chuyện về tiết mục văn nghệ của trường thú vị hơn nè.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_06','V934','小周',6,'好，我们聊晚会，不聊私人家庭收支话题。','hǎo， wǒ men liáo wǎn huì， bù liáo sī rén jiā tíng shōu zhī huà tí。','Ừ, vậy mình bàn chuyện văn nghệ thôi, không nhắc đến chuyện thu chi riêng tư của gia đình nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_07','V934','阮明',7,'感谢理解，各自保留一点私人空间相处更舒服。','gǎn xiè lǐ jiě， gè zì bǎo liú yì diǎn sī rén kōng jiān xiāng chǔ gèng shū fú。','Cảm ơn cậu đã hiểu, mỗi người giữ chút không gian riêng thì chơi với nhau thoải mái hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT935','SXH6','毕业前夕和要好的朋友约定，回国后定期线上联络',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V935','SIT935','P1','suon_se','ban_chinh_thuc',NULL,'毕业分离时好友会主动约定长期联络方式，国内年轻人十分看重长久稳定的友谊，不会因异地轻易断联。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_01','V935','阮明',1,'等我毕业回越南，我们也要保持联系，不能慢慢断了往来。','děng wǒ bì yè huí yuè nán， wǒ men yě yào bǎo chí lián xì， bù néng màn màn duàn le wǎng lái。','Đợi tôi tốt nghiệp về Việt Nam rồi, chúng ta vẫn phải giữ liên lạc, không được để quan hệ nhạt dần đâu đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_02','V935','苏雯',2,'放心，每月固定一次线上视频，分享各自工作、生活近况。','fàng xīn， měi yuè gù dìng yī cì xiàn shàng shì pín， fēn xiǎng gè zì gōng zuò、 shēng huó jìn kuàng。','Yên tâm đi, mỗi tháng cố định gọi video một lần, chia sẻ tình hình công việc và cuộc sống của mỗi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_03','V935','阮明',3,'节假日互相寄本国小特产，线上聊天弥补不能线下见面的遗憾。','jié jià rì hù xiāng jì běn guó xiǎo tè chǎn， xiàn shàng liáo tiān mí bǔ bù néng xiàn xià jiàn miàn de yí hàn。','Vào các dịp lễ thì gửi cho nhau chút đặc sản quê mình, trò chuyện online cũng bù đắp phần nào cho việc không gặp trực tiếp được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_04','V935','苏雯',4,'不管距离多远，我们的友谊不会因为回国分开变淡。','bù guǎn jù lí duō yuǎn， wǒ men de yǒu yì bú huì yīn wèi huí guó fēn kāi biàn dàn。','Dù khoảng cách có xa đến đâu, tình bạn của chúng ta cũng sẽ không nhạt đi chỉ vì ai đó về nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_05','V935','阮明',5,'回国之后时差一小时，提前约定双方都空闲的视频时段。','huí guó zhī hòu shí chà yī xiǎo shí， tí qián yuē dìng shuāng fāng dōu kòng xián de shì pín shí duàn。','Sau khi về nước thì lệch múi giờ một tiếng, mình hẹn trước khung giờ mà cả hai đều rảnh để gọi video.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_06','V935','苏雯',6,'我记好约定，毕业之后按时线上叙旧。','wǒ jì hǎo yuē dìng， bì yè zhī hòu àn shí xiàn shàng xù jiù。','Tôi sẽ ghi nhớ lời hẹn này, sau khi tốt nghiệp sẽ đúng giờ lên online ôn lại chuyện xưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_07','V935','阮明',7,'很幸运在校期间认识你，长久维持这份跨国友谊。','hěn xìng yùn zài xiào qī jiān rèn shí nǐ， cháng jiǔ wéi chí zhè fèn kuà guó yǒu yì。','Thật may mắn khi quen được cậu trong thời gian học ở trường, mong tình bạn xuyên quốc gia này sẽ bền lâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1001','SKC1','深夜高烧腹泻无校医，求助室友陪同去校外急诊',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1001','SIT1001','P1','twist','tuy_y',NULL,'国内多数高校校医仅白天值班，夜间急症只能前往社区24小时医院，室友之间临时垫付医药费是很常见的互助方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_01','V1001','阮明',1,'晓晓，你醒一下好不好，我难受得快撑不住啦。','xiǎo xiǎo， nǐ xǐng yī xià hǎo bù hǎo， wǒ nán shòu dé kuài chēng bú zhù la。','Hiểu Hiểu, cậu dậy một chút được không, tớ khó chịu sắp chịu không nổi rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_02','V1001','林晓',2,'怎么了明哥？现在都凌晨两点了，你哪里不舒服啊？','zěn me le míng gē？ xiàn zài dōu líng chén liǎng diǎn le， nǐ nǎ lǐ bù shū fú a？','Sao vậy anh Minh? Giờ đã hai giờ sáng rồi, anh khó chịu ở đâu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_03','V1001','阮明',3,'我突然发高烧，还一直拉肚子，浑身发软走不动路呢。','wǒ tū rán fā gāo shāo， hái yì zhí lā dù zi， hún shēn fā ruǎn zǒu bù dòng lù ne。','Tớ đột nhiên sốt cao, lại còn tiêu chảy liên tục, người mềm nhũn không đi nổi luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_04','V1001','林晓',4,'天呐，校医室早就关门了，要不我陪你去附近的24小时急诊吧？','tiān nà， xiào yī shì zǎo jiù guān mén le， yào bù wǒ péi nǐ qù fù jìn de 24 xiǎo shí jí zhěn ba？','Trời ơi, phòng y tế trường đóng cửa từ lâu rồi, hay để tớ đưa anh đi phòng cấp cứu 24 giờ gần đây nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_05','V1001','阮明',5,'可以吗？可是我身上现金不多，手机支付也有点麻烦诶。','kě yǐ ma？ kě shì wǒ shēn shàng xiàn jīn bù duō， shǒu jī zhī fù yě yǒu diǎn má fán éi。','Được không đấy? Nhưng tớ không mang nhiều tiền mặt, thanh toán qua điện thoại cũng hơi phiền nữa.','AM12') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_06','V1001','林晓',6,'没事，我先帮你垫付医药费，之后你再转我就行，先看病要紧吧。','méi shì， wǒ xiān bāng nǐ diàn fù yī yào fèi， zhī hòu nǐ zài zhuǎn wǒ jiù xíng， xiān kàn bìng yào jǐn ba。','Không sao, để tớ ứng tiền khám bệnh trước, sau đó anh chuyển lại cho tớ là được, giờ khám bệnh mới quan trọng.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_07','V1001','阮明',7,'太谢谢你了，我现在站起来都头晕，得麻烦你扶我一下啦。','tài xiè xiè nǐ le， wǒ xiàn zài zhàn qǐ lái dōu tóu yūn， dé má fán nǐ fú wǒ yī xià la。','Cảm ơn cậu nhiều lắm, giờ tớ đứng dậy còn thấy chóng mặt, phải phiền cậu đỡ tớ một tay rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_08','V1001','林晓',8,'别客气，快披上厚外套，外面夜里风很大，我们马上出门。','bié kè qì， kuài pī shàng hòu wài tào， wài miàn yè lǐ fēng hěn dà， wǒ men mǎ shàng chū mén。','Đừng khách sáo, mau khoác áo khoác dày vào, ngoài trời đêm nay gió to lắm, mình đi ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1002','SKC1','宿舍水管爆裂积水，紧急联系后勤抢修止损',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1002','SIT1002','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍后勤维修分时段报修，突发漏水这类险情可直接拨打应急专线，不用走线上预约流程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_01','V1002','阮明',1,'张师傅您好，我是3栋402宿舍的留学生阮明，出事了！','zhāng shī fù nín hǎo， wǒ shì 3 dòng 402 sù shè de liú xué shēng ruǎn míng， chū shì le！','Chào chú Trương, cháu là du học sinh Nguyễn Minh ở phòng 402 tòa 3, có chuyện rồi ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_02','V1002','张师傅',2,'同学别慌，慢慢说，宿舍里面发生什么事啦？','tóng xué bié huāng， màn màn shuō， sù shè lǐ miàn fā shēng shén me shì la？','Em đừng hoảng, từ từ nói, trong phòng xảy ra chuyện gì vậy?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_03','V1002','阮明',3,'卫生间水龙头水管突然爆裂，地上全是积水，快漫到书桌了啊。','wèi shēng jiān shuǐ lóng tóu shuǐ guǎn tū rán bào liè， dì shàng quán shì jī shuǐ， kuài màn dào shū zhuō le a。','Ống nước vòi rửa trong nhà vệ sinh đột nhiên bị nứt vỡ, sàn nhà toàn là nước, sắp tràn tới bàn học rồi ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_04','V1002','张师傅',4,'我知道了，你先把卫生间总水阀关掉，防止水继续流出来吧。','wǒ zhī dào le， nǐ xiān bǎ wèi shēng jiān zǒng shuǐ fá guān diào， fáng zhǐ shuǐ jì xù liú chū lái ba。','Chú biết rồi, em khóa van tổng nước ở nhà vệ sinh lại trước đã, để nước khỏi chảy tiếp ra ngoài.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_05','V1002','阮明',5,'我刚试过，总阀拧不动，完全关不上，积水越积越多呢。','wǒ gāng shì guò， zǒng fá níng bù dòng， wán quán guān bù shàng， jī shuǐ yuè jī yuè duō ne。','Cháu vừa thử rồi, van tổng vặn không được, không tài nào khóa lại, nước cứ đọng ngày càng nhiều ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_06','V1002','张师傅',6,'行，我现在带上工具十分钟就上楼，你先用拖把、脸盆先舀水控水。','xíng， wǒ xiàn zài dài shàng gōng jù shí fēn zhōng jiù shàng lóu， nǐ xiān yòng tuō bǎ、 liǎn pén xiān yǎo shuǐ kòng shuǐ。','Được, chú mang dụng cụ lên ngay, mười phút nữa là tới, em cứ dùng cây lau nhà, chậu để tát nước ra trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_07','V1002','阮明',7,'好的师傅，我马上清理积水，麻烦您尽快过来，怕泡坏地板。','hǎo de shī fù， wǒ mǎ shàng qīng lǐ jī shuǐ， má fán nín jǐn kuài guò lái， pà pào huài dì bǎn。','Vâng chú, cháu dọn nước ngay đây, phiền chú đến sớm giúp cháu, cháu sợ ngấm hỏng sàn nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_08','V1002','张师傅',8,'放心，我这边立刻出发，到宿舍楼下给你打电话。','fàng xīn， wǒ zhè biān lì kè chū fā， dào sù shè lóu xià gěi nǐ dǎ diàn huà。','Yên tâm, chú xuất phát ngay bây giờ, đến dưới ký túc xá sẽ gọi điện cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1003','SKC1','就餐食物严重过敏无抗过敏药，同学送医急救',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1003','SIT1003','P1','twist','tuy_y',NULL,'国内医院急诊可先救治后补登记证件，留学生就诊出示居留许可即可登记。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_01','V1003','阮明',1,'小雨，我身上起了好多红疹，喘不上气，好像过敏了啊。','xiǎo yǔ， wǒ shēn shàng qǐ le hǎo duō hóng zhěn， chuǎn bù shàng qì， hǎo xiàng guò mǐn le a。','Tiểu Vũ, người tớ nổi đầy mẩn đỏ, thở không nổi, hình như bị dị ứng rồi.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_02','V1003','陈雨',2,'你中午吃什么东西了？宿舍有没有备抗过敏药呢？','nǐ zhōng wǔ chī shén me dōng xī le？ sù shè yǒu méi yǒu bèi kàng guò mǐn yào ne？','Trưa cậu ăn gì thế? Trong phòng có sẵn thuốc chống dị ứng không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_03','V1003','阮明',3,'中午食堂的海鲜小炒，我没带过敏药，喉咙越来越肿啦。','zhōng wǔ shí táng de hǎi xiān xiǎo chǎo， wǒ méi dài guò mǐn yào， hóu lóng yuè lái yuè zhǒng la。','Trưa tớ ăn món hải sản xào ở căng tin, tớ không mang theo thuốc dị ứng, cổ họng cứ sưng lên mãi rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_04','V1003','陈雨',4,'情况不对劲，不能硬扛，我现在骑车带你去医院急诊吧。','qíng kuàng bú duì jìn， bù néng yìng káng， wǒ xiàn zài qí chē dài nǐ qù yī yuàn jí zhěn ba。','Tình hình này không ổn rồi, không thể cố chịu được đâu, giờ tớ chở cậu bằng xe đạp đi cấp cứu bệnh viện nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_05','V1003','阮明',5,'可是我身份证、居留卡都放在宿舍柜子里，没随身带诶。','kě shì wǒ shēn fèn zhèng、 jū liú kǎ dōu fàng zài sù shè guì zi lǐ， méi suí shēn dài éi。','Nhưng chứng minh thư với thẻ tạm trú của tớ để trong tủ ở phòng, tớ không mang theo người nữa.','AM12') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_06','V1003','陈雨',6,'先去医院，我跟辅导员说明情况，等下回宿舍帮你取证件。','xiān qù yī yuàn， wǒ gēn fǔ dǎo yuán shuō míng qíng kuàng， děng xià huí sù shè bāng nǐ qǔ zhèng jiàn。','Cứ đi bệnh viện trước đã, tớ sẽ nói rõ tình hình với thầy cô chủ nhiệm, lát nữa về phòng lấy giấy tờ giúp cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_07','V1003','阮明',7,'真的太麻烦你了，我现在手脚都有点发麻，站不稳。','zhēn de tài má fán nǐ le， wǒ xiàn zài shǒu jiǎo dōu yǒu diǎn fā má， zhàn bù wěn。','Thật sự làm phiền cậu quá, giờ tay chân tớ hơi tê rồi, đứng không vững nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_08','V1003','陈雨',8,'别说话，扶好我，我们现在立刻往校门口医院赶。','bié shuō huà， fú hǎo wǒ， wǒ men xiàn zài lì kè wǎng xiào mén kǒu yī yuàn gǎn。','Đừng nói nữa, bám chặt vào tớ, mình đi ngay tới bệnh viện ở cổng trường bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1004','SKC1','宿舍大功率电器短路冒烟断电，联系宿管排查隐患',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1004','SIT1004','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍严禁大功率电煮锅、电暖锅等电器，违规使用引发电路故障需自行承担维修损失。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_01','V1004','阮明',1,'李阿姨，我是5栋206的阮明，宿舍插座冒烟跳闸了！','lǐ ā yí， wǒ shì 5 dòng 206 de ruǎn míng， sù shè chā zuò mào yān tiào zhá le！','Cô Lý ơi, cháu là Nguyễn Minh ở phòng 206 tòa 5, ổ cắm điện trong phòng bốc khói và nhảy cầu rồi ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_02','V1004','李宿管',2,'你先别靠近插座，有没有用水去碰线路啊？','nǐ xiān bié kào jìn chā zuò， yǒu méi yǒu yòng shuǐ qù pèng xiàn lù a？','Em đừng lại gần ổ cắm, có dùng nước chạm vào đường dây không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_03','V1004','阮明',3,'没有，我第一时间拔掉了所有插头，房间现在完全断电了呢。','méi yǒu， wǒ dì yī shí jiān bá diào le suǒ yǒu chā tóu， fáng jiān xiàn zài wán quán duàn diàn le ne。','Dạ không, cháu rút hết phích cắm ngay lập tức rồi, giờ phòng cháu mất điện hoàn toàn ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_04','V1004','李宿管',4,'是什么电器在用的时候出问题的，大功率电煮锅吗？','shì shén me diàn qì zài yòng de shí hòu chū wèn tí de， dà gōng lǜ diàn zhǔ guō ma？','Là thiết bị điện gì đang dùng thì bị lỗi vậy, nồi nấu điện công suất lớn à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_05','V1004','阮明',5,'对，我刚煮完汤，一拔插头插座就冒出黑烟，吓死我了。','duì， wǒ gāng zhǔ wán tāng， yī bá chā tóu chā zuò jiù mào chū hēi yān， xià sǐ wǒ le。','Dạ đúng, cháu vừa nấu xong nồi canh, vừa rút phích ra là ổ cắm bốc khói đen luôn, cháu sợ muốn chết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_06','V1004','李宿管',6,'我马上带电工过来检查电路，你们宿舍近期先别使用大功率厨具。','wǒ mǎ shàng dài diàn gōng guò lái jiǎn chá diàn lù， nǐ men sù shè jìn qī xiān bié shǐ yòng dà gōng lǜ chú jù。','Cô đưa thợ điện lên kiểm tra đường dây ngay, phòng các em thời gian tới tạm thời đừng dùng thiết bị bếp công suất lớn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_07','V1004','阮明',7,'好的阿姨，我不会再私自用电锅，等电工确认安全再说吧。','hǎo de ā yí， wǒ bú huì zài sī zì yòng diàn guō， děng diàn gōng què rèn ān quán zài shuō ba。','Vâng cô, cháu sẽ không tự ý dùng nồi điện nữa, đợi thợ điện xác nhận an toàn rồi tính tiếp ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_08','V1004','李宿管',8,'你们先在走廊稍等片刻，避免电路残留隐患伤到你们。','nǐ men xiān zài zǒu láng shāo děng piàn kè， bì miǎn diàn lù cán liú yǐn huàn shāng dào nǐ men。','Các em cứ đợi ở hành lang một lát, tránh để đường dây còn sót nguy hiểm làm các em bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1005','SKC1','晾晒衣物坠落楼下险些砸伤路人，下楼道歉处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1005','SIT1005','P1','that_bai_nhe','tuy_y',NULL,'国内居民楼、学生公寓高空坠物属于危险行为，一旦伤人需承担全部赔偿责任，物业会对违规住户通报批评。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_01','V1005','阮明',1,'阿姨实在对不起！刚才衣服从阳台掉下来，差点砸到您了吧？','ā yí shí zài duì bù qǐ！ gāng cái yī fú cóng yáng tái diào xià lái， chà diǎn zá dào nín le ba？','Cô ơi, cháu thật sự xin lỗi! Vừa nãy quần áo từ ban công rơi xuống, suýt trúng cô phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_02','V1005','王阿姨',2,'小伙子，你这衣服飘下来吓我一跳，还好我及时躲开了啊。','xiǎo huǒ zi， nǐ zhè yī fú piāo xià lái xià wǒ yī tiào， hái hǎo wǒ jí shí duǒ kāi le a。','Cậu trai này, quần áo bay xuống làm cô giật cả mình, may mà cô né kịp đấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_03','V1005','阮明',3,'都怪我没把晾衣架固定牢，我现在马上捡起来，真的很抱歉呢。','dōu guài wǒ méi bǎ liàng yī jià gù dìng láo， wǒ xiàn zài mǎ shàng jiǎn qǐ lái， zhēn de hěn bào qiàn ne。','Tại cháu không cố định giá phơi cho chắc, giờ cháu nhặt lên ngay đây, thật sự xin lỗi cô ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_04','V1005','王阿姨',4,'下次一定要注意，楼下行人很多，砸到人后果可就严重啦。','xià cì yí dìng yào zhù yì， lóu xià xíng rén hěn duō， zá dào rén hòu guǒ kě jiù yán zhòng la。','Lần sau nhớ cẩn thận đấy, dưới này người qua lại nhiều lắm, trúng phải người thì hậu quả nghiêm trọng lắm nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_05','V1005','阮明',5,'我记住了，以后晾晒一定加固，不会再发生这种事了。','wǒ jì zhù le， yǐ hòu liàng shài yí dìng jiā gù， bú huì zài fā shēng zhè zhǒng shì le。','Cháu ghi nhớ rồi ạ, sau này phơi đồ nhất định sẽ gia cố chắc chắn, sẽ không để xảy ra chuyện thế này nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_06','V1005','王阿姨',6,'光说没用，刚刚还有小朋友在楼下玩，万一砸伤孩子怎么办？','guāng shuō méi yòng， gāng gāng hái yǒu xiǎo péng yǒu zài lóu xià wán， wàn yī zá shāng hái zi zěn me bàn？','Nói suông thì có ích gì, vừa nãy còn có mấy đứa nhỏ chơi dưới này, lỡ trúng phải trẻ con thì sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_07','V1005','阮明',7,'是我考虑不周，我这就上楼换更稳固的晾晒支架。','shì wǒ kǎo lǜ bù zhōu， wǒ zhè jiù shàng lóu huàn gèng wěn gù de liàng shài zhī jià。','Là cháu suy nghĩ không chu đáo, cháu lên phòng đổi giá phơi chắc chắn hơn ngay đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_08','V1005','王阿姨',8,'行，下次多留心，这次我就不跟宿管反映了。','xíng， xià cì duō liú xīn， zhè cì wǒ jiù bù gēn sù guǎn fǎn yìng le。','Được rồi, lần sau để ý hơn nhé, lần này cô sẽ không báo cho quản lý ký túc xá đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1006','SKC1','夜间突发眩晕耳鸣无法行走，拨打校内24小时应急电话',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1006','SIT1006','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有24小时学生应急值班专线，仅限夜间突发身体、安全险情使用，日常小事不建议拨打。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_01','V1006','阮明',1,'您好，这里是留学生公寓6栋301，我是越南学生阮明，现在身体很不舒服。','nín hǎo， zhè lǐ shì liú xué shēng gōng yù 6 dòng 301， wǒ shì yuè nán xué shēng ruǎn míng， xiàn zài shēn tǐ hěn bù shū fú。','Chào cô, đây là phòng 301 tòa 6 khu ký túc du học sinh, cháu là sinh viên Việt Nam Nguyễn Minh, giờ người cháu rất khó chịu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_02','V1006','王老师',2,'同学你别着急，慢慢讲，你现在是什么症状呢？','tóng xué nǐ bié zháo jí， màn màn jiǎng， nǐ xiàn zài shì shén me zhèng zhuàng ne？','Em đừng lo, từ từ nói, giờ em có triệu chứng gì vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_03','V1006','阮明',3,'我突然严重耳鸣，天旋地转，根本没办法站起来走路啊。','wǒ tū rán yán zhòng ěr míng， tiān xuán dì zhuàn， gēn běn méi bàn fǎ zhàn qǐ lái zǒu lù a。','Cháu đột nhiên bị ù tai nặng, trời đất quay cuồng, hoàn toàn không đứng dậy đi lại được ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_04','V1006','王老师',4,'房间里现在有人陪同你吗，身边有没有热水、止痛药？','fáng jiān lǐ xiàn zài yǒu rén péi tóng nǐ ma， shēn biān yǒu méi yǒu rè shuǐ、 zhǐ tòng yào？','Trong phòng giờ có ai ở cùng em không, bên cạnh có nước ấm hay thuốc giảm đau không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_05','V1006','阮明',5,'室友今天回家了，只有我一个人在宿舍，什么药都没有呢。','shì yǒu jīn tiān huí jiā le， zhǐ yǒu wǒ yí gè rén zài sù shè， shén me yào dōu méi yǒu ne。','Bạn cùng phòng hôm nay về nhà rồi, chỉ có mình cháu trong phòng, không có thuốc gì cả ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_06','V1006','王老师',6,'我马上联系校应急医护人员上楼，你先靠在床边不要乱动。','wǒ mǎ shàng lián xì xiào yìng jí yī hù rén yuán shàng lóu， nǐ xiān kào zài chuáng biān bú yào luàn dòng。','Cô liên hệ nhân viên y tế cấp cứu của trường lên ngay, em cứ dựa vào thành giường, đừng cử động lung tung nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_07','V1006','阮明',7,'麻烦您快一点，我现在闭上眼睛都还是不停头晕。','má fán nín kuài yì diǎn， wǒ xiàn zài bì shàng yǎn jīng dōu hái shì bù tíng tóu yūn。','Phiền cô nhanh giúp cháu với, giờ cháu nhắm mắt lại vẫn cứ chóng mặt không dứt ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_08','V1006','王老师',8,'五分钟内医护人员就到，保持电话畅通，有情况随时跟我说。','wǔ fēn zhōng nèi yī hù rén yuán jiù dào， bǎo chí diàn huà chàng tōng， yǒu qíng kuàng suí shí gēn wǒ shuō。','Trong vòng năm phút nhân viên y tế sẽ tới, giữ điện thoại thông suốt nhé, có gì cứ báo cho cô ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1007','SKC1','网约车司机恶意绕道加价，拨打平台客服紧急维权',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1007','SIT1007','P1','twist','chinh_thuc',NULL,'国内网约车全程平台计价，司机私下索要现金加价属于违规，乘客可直接留存录音、行程记录投诉全额退款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_01','V1007','阮明',1,'您好，我要投诉刚才接单的网约车司机，存在恶意绕道加价行为。','nín hǎo， wǒ yào tóu sù gāng cái jiē dān de wǎng yuē chē sī jī， cún zài è yì rào dào jiā jià xíng wéi。','Xin chào, tôi muốn khiếu nại tài xế xe công nghệ vừa nhận chuyến, có hành vi cố tình đi đường vòng để tăng giá cước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_02','V1007','客服',2,'您好先生，请提供您的订单编号，我这边调取行程记录核对吧。','nín hǎo xiān shēng， qǐng tí gōng nín de dìng dān biān hào， wǒ zhè biān diào qǔ xíng chéng jì lù hé duì ba。','Chào anh, xin anh cung cấp mã đơn hàng, tôi sẽ kiểm tra lại lộ trình di chuyển ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_03','V1007','阮明',3,'订单编号是724915，明明导航直达，司机故意绕远路还多收钱呢。','dìng dān biān hào shì 724915， míng míng dǎo háng zhí dá， sī jī gù yì rào yuǎn lù hái duō shōu qián ne。','Mã đơn hàng là 724915, rõ ràng định vị chỉ đường thẳng mà tài xế cố tình đi vòng xa hơn còn thu thêm tiền.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_04','V1007','客服',4,'我查看路线了，确实存在偏离导航的绕行路段，非常抱歉给您带来不好体验。','wǒ chá kàn lù xiàn le， què shí cún zài piān lí dǎo háng de rào xíng lù duàn， fēi cháng bào qiàn gěi nín dài lái bù hǎo tǐ yàn。','Tôi đã kiểm tra lộ trình rồi, đúng là có đoạn đường đi lệch khỏi chỉ dẫn định vị, rất xin lỗi vì đã mang lại trải nghiệm không tốt cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_05','V1007','阮明',5,'司机还态度很差，直接跟我索要额外现金，不接受线上结算啊。','sī jī hái tài dù hěn chà， zhí jiē gēn wǒ suǒ yào é wài xiàn jīn， bù jiē shòu xiàn shàng jié suàn a。','Tài xế còn thái độ rất tệ, trực tiếp đòi tôi trả thêm tiền mặt, không chịu thanh toán online.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_06','V1007','客服',6,'我们会对司机进行处罚，多收取的费用会在1-3个工作日原路退还。','wǒ men huì duì sī jī jìn xíng chǔ fá， duō shōu qǔ de fèi yòng huì zài 1-3 gè gōng zuò rì yuán lù tuì huán。','Chúng tôi sẽ xử lý kỷ luật tài xế, khoản phí thu thêm sẽ được hoàn trả lại theo đường cũ trong vòng 1-3 ngày làm việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_07','V1007','阮明',7,'能不能尽快处理？我等下还要打车去学校，担心再遇到同类情况。','néng bù néng jǐn kuài chǔ lǐ？ wǒ děng xià hái yào dǎ chē qù xué xiào， dān xīn zài yù dào tóng lèi qíng kuàng。','Có thể xử lý nhanh giúp tôi không? Lát nữa tôi còn phải bắt xe đi học, lo lại gặp phải tình huống tương tự.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_08','V1007','客服',8,'我这边加急标记您的投诉单，处理结果会以短信通知您的。','wǒ zhè biān jiā jí biāo jì nín de tóu sù dān， chǔ lǐ jié guǒ huì yǐ duǎn xìn tōng zhī nín de。','Tôi sẽ đánh dấu khẩn cấp cho đơn khiếu nại của anh, kết quả xử lý sẽ được thông báo qua tin nhắn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1008','SKC1','骑行共享单车摔倒扭伤，向路人求助简单伤口处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1008','SIT1008','P1','suon_se','tuy_y',NULL,'国内很多年轻人会随身备简易消毒用品，路人遇到受伤行人大多愿意主动提供临时帮助。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_01','V1008','阮明',1,'不好意思打扰一下，我骑车摔倒擦伤膝盖，您有碘伏吗？','bù hǎo yì sī dǎ rǎo yī xià， wǒ qí chē shuāi dǎo cā shāng xī gài， nín yǒu diǎn fú ma？','Xin lỗi làm phiền một chút, tớ đi xe đạp bị ngã trầy đầu gối, cậu có thuốc sát trùng iốt không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_02','V1008','刘姑娘',2,'哎呀，你摔得看着挺疼的，我包里刚好有消毒湿巾和创可贴呢。','āi yā， nǐ shuāi dé kàn zhe tǐng téng de， wǒ bāo lǐ gāng hǎo yǒu xiāo dú shī jīn hé chuàng kě tiē ne。','Ôi, cậu ngã nhìn đau ghê, túi tớ vừa hay có khăn giấy khử trùng với băng cá nhân đây.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_03','V1008','阮明',3,'太感谢你了，刚才刹车打滑摔在路边，伤口一直在流血啊。','tài gǎn xiè nǐ le， gāng cái shā chē dǎ huá shuāi zài lù biān， shāng kǒu yì zhí zài liú xiě a。','Cảm ơn cậu nhiều lắm, vừa nãy phanh gấp trượt bánh ngã bên đường, vết thương cứ chảy máu mãi.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_04','V1008','刘姑娘',4,'你先坐在台阶上别动，我帮你清理一下伤口，别沾到灰尘吧。','nǐ xiān zuò zài tái jiē shàng bié dòng， wǒ bāng nǐ qīng lǐ yī xià shāng kǒu， bié zhān dào huī chén ba。','Cậu ngồi yên trên bậc thềm đi, để tớ giúp lau vết thương, đừng để dính bụi bẩn vào nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_05','V1008','阮明',5,'好，麻烦你了，我自己没随身携带急救小物件，太疏忽了。','hǎo， má fán nǐ le， wǒ zì jǐ méi suí shēn xié dài jí jiù xiǎo wù jiàn， tài shū hū le。','Được, phiền cậu rồi, tớ không mang theo đồ sơ cứu bên người, sơ suất quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_06','V1008','刘姑娘',6,'下次骑车慢一点，雨天路面滑很容易摔倒，记得小心一点。','xià cì qí chē màn yì diǎn， yǔ tiān lù miàn huá hěn róng yì shuāi dǎo， jì de xiǎo xīn yì diǎn。','Lần sau đi xe chậm lại nhé, trời mưa đường trơn dễ ngã lắm, nhớ cẩn thận hơn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_07','V1008','阮明',7,'我记住啦，处理完我自己慢慢扶车回去，不耽误你赶路。','wǒ jì zhù la， chǔ lǐ wán wǒ zì jǐ màn màn fú chē huí qù， bù dān wù nǐ gǎn lù。','Tớ nhớ rồi, xử lý xong tớ tự dắt xe từ từ về, không làm chậm trễ việc của cậu đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1009','SKC1','外出迷路手机没电关机，向商铺店员借手机联系好友',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1009','SIT1009','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内商铺店主出于防骗顾虑，大多不愿外借私人手机，街边共享充电宝是外出应急充电主流方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_01','V1009','阮明',1,'老板您好，不好意思打扰，我的手机没电关机了，能借您手机打个电话吗？','lǎo bǎn nín hǎo， bù hǎo yì sī dǎ rǎo， wǒ de shǒu jī méi diàn guān jī le， néng jiè nín shǒu jī dǎ gè diàn huà ma？','Chào anh, xin lỗi làm phiền anh, điện thoại của em hết pin tắt máy rồi, anh cho em mượn điện thoại gọi một cuộc được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_02','V1009','赵老板',2,'借手机可以，你先说一下要联系谁，打多久电话呀？','jiè shǒu jī kě yǐ， nǐ xiān shuō yī xià yào lián xì shuí， dǎ duō jiǔ diàn huà ya？','Mượn điện thoại thì được, nhưng em nói xem định gọi cho ai, gọi bao lâu vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_03','V1009','阮明',3,'我和同学走散迷路了，就打两分钟，跟他说我现在的位置就行呢。','wǒ hé tóng xué zǒu sàn mí lù le， jiù dǎ liǎng fēn zhōng， gēn tā shuō wǒ xiàn zài de wèi zhì jiù xíng ne。','Em bị lạc mất bạn học rồi, chỉ gọi khoảng hai phút thôi, nói cho bạn ấy biết vị trí hiện tại của em là được rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_04','V1009','赵老板',4,'现在陌生人借手机诈骗太多，我不太方便直接把手机给你啊。','xiàn zài mò shēng rén jiè shǒu jī zhà piàn tài duō， wǒ bù tài fāng biàn zhí jiē bǎ shǒu jī gěi nǐ a。','Bây giờ chuyện người lạ mượn điện thoại để lừa đảo nhiều lắm, tôi không tiện đưa thẳng điện thoại cho em đâu.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_05','V1009','阮明',5,'我是附近大学的留学生，可以出示我的居留卡给您看证明身份。','wǒ shì fù jìn dà xué de liú xué shēng， kě yǐ chū shì wǒ de jū liú kǎ gěi nín kàn zhèng míng shēn fèn。','Em là du học sinh trường đại học gần đây, em có thể đưa thẻ cư trú cho anh xem để chứng minh thân phận ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_06','V1009','赵老板',6,'证件我也不方便仔细核对，你去对面便利店租借共享充电宝吧。','zhèng jiàn wǒ yě bù fāng biàn zǐ xì hé duì， nǐ qù duì miàn biàn lì diàn zū jiè gòng xiǎng chōng diàn bǎo ba。','Giấy tờ thì tôi cũng không tiện kiểm tra kỹ đâu, em qua cửa hàng tiện lợi đối diện thuê pin sạc dự phòng dùng chung đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_07','V1009','阮明',7,'好吧，我现在就过去，真是麻烦您了。','hǎo ba， wǒ xiàn zài jiù guò qù， zhēn shì má fán nín le。','Vâng, em qua đó ngay đây, thật sự làm phiền anh quá.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_08','V1009','赵老板',8,'理解一下，我们开店也怕遇到骗子，多多包涵哈。','lǐ jiě yī xià， wǒ men kāi diàn yě pà yù dào piàn zi， duō duō bāo hán hā。','Em thông cảm nhé, chúng tôi mở tiệm cũng sợ gặp phải kẻ lừa đảo, mong em bỏ qua cho nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1010','SKC1','背包在商场被小偷顺手牵羊，前往附近派出所做笔录',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1010','SIT1010','P1','twist','chinh_thuc',NULL,'外国人丢失随身财物报案，需携带护照、居留许可，笔录信息会同步登记出入境系统。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_01','V1010','阮明',1,'警官您好，我要报案，我的背包在商场餐饮区被偷走了。','jǐng guān nín hǎo， wǒ yào bào àn， wǒ de bēi bāo zài shāng chǎng cān yǐn qū bèi tōu zǒu le。','Chào cán bộ, tôi muốn trình báo, ba lô của tôi đã bị đánh cắp tại khu ẩm thực trong trung tâm thương mại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_02','V1010','周警官',2,'先坐下来，把你的姓名、国籍、居留证件信息跟我说一下。','xiān zuò xià lái， bǎ nǐ de xìng míng、 guó jí、 jū liú zhèng jiàn xìn xī gēn wǒ shuō yī xià。','Anh ngồi xuống trước đã, cho tôi biết họ tên, quốc tịch và thông tin giấy tờ cư trú của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_03','V1010','阮明',3,'我叫阮明，越南留学生，包里有银行卡、耳机还有课堂笔记呢。','wǒ jiào ruǎn míng， yuè nán liú xué shēng， bāo lǐ yǒu yín háng kǎ、 ěr jī hái yǒu kè táng bǐ jì ne。','Tôi tên là Nguyễn Minh, du học sinh Việt Nam, trong ba lô có thẻ ngân hàng, tai nghe và cả vở ghi chép trên lớp.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_04','V1010','周警官',4,'丢失的具体时间、商场楼层、座位位置，你仔细回忆清楚吧。','diū shī de jù tǐ shí jiān、 shāng chǎng lóu céng、 zuò wèi wèi zhì， nǐ zǐ xì huí yì qīng chǔ ba。','Anh nhớ lại thật kỹ thời gian cụ thể bị mất, tầng nào của trung tâm thương mại, và vị trí chỗ ngồi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_05','V1010','阮明',5,'大概四十分钟前，我去取餐转身几十秒，背包就不见了啊。','dà gài sì shí fēn zhōng qián， wǒ qù qǔ cān zhuǎn shēn jǐ shí miǎo， bēi bāo jiù bú jiàn le a。','Khoảng bốn mươi phút trước, tôi đi lấy đồ ăn, quay người chưa đầy một phút thì ba lô đã biến mất.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_06','V1010','周警官',6,'我们会调取监控录像，不过商场人流大，找回物品难度不小。','wǒ men huì diào qǔ jiān kòng lù xiàng， bù guò shāng chǎng rén liú dà， zhǎo huí wù pǐn nán dù bù xiǎo。','Chúng tôi sẽ trích xuất camera giám sát, nhưng trung tâm thương mại đông người qua lại nên việc tìm lại đồ không hề dễ dàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_07','V1010','阮明',7,'我的银行卡还没挂失，能不能麻烦您告诉我挂失银行的电话？','wǒ de yín háng kǎ hái méi guà shī， néng bù néng má fán nín gào sù wǒ guà shī yín háng de diàn huà？','Thẻ ngân hàng của tôi vẫn chưa báo mất, phiền anh cho tôi xin số điện thoại để báo mất thẻ được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_08','V1010','周警官',8,'我写在纸条上给你，做完笔录尽快联系银行冻结卡片。','wǒ xiě zài zhǐ tiáo shàng gěi nǐ， zuò wán bǐ lù jǐn kuài lián xì yín háng dòng jié kǎ piàn。','Tôi sẽ ghi ra giấy cho anh, sau khi lập biên bản xong anh hãy liên hệ ngay với ngân hàng để khóa thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1011','SKC1','暴雨导致郊区公交全线停运，求助社区工作人员临时安置',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1011','SIT1011','P1','suon_se','ban_chinh_thuc',NULL,'国内社区服务中心对受极端天气滞留的路人提供免费临时休息、热水充电等便民服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_01','V1011','阮明',1,'您好，外面暴雨所有公交都停了，我回不去学校，能临时待在这里吗？','nín hǎo， wài miàn bào yǔ suǒ yǒu gōng jiāo dōu tíng le， wǒ huí bù qù xué xiào， néng lín shí dài zài zhè lǐ ma？','Chào chị, ngoài trời mưa to nên xe buýt ngừng chạy hết rồi, em không về trường được, em có thể tạm ở đây được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_02','V1011','小吴',2,'同学别着急，先跟我说下你的学校地址，还有身上有没有雨具？','tóng xué bié zháo jí， xiān gēn wǒ shuō xià nǐ de xué xiào dì zhǐ， hái yǒu shēn shàng yǒu méi yǒu yǔ jù？','Em đừng lo, nói cho chị biết địa chỉ trường của em trước đã, với lại em có mang theo đồ che mưa gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_03','V1011','阮明',3,'我是外国语大学留学生，出门没带伞，手机快没电没法打车呢。','wǒ shì wài guó yǔ dà xué liú xué shēng， chū mén méi dài sǎn， shǒu jī kuài méi diàn méi fǎ dǎ chē ne。','Em là du học sinh trường Đại học Ngoại ngữ, lúc ra ngoài không mang ô, điện thoại lại sắp hết pin nên không gọi xe được ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_04','V1011','小吴',4,'外面积水太深网约车也进不来，社区服务站可以临时休息到雨停。','wài miàn jī shuǐ tài shēn wǎng yuē chē yě jìn bù lái， shè qū fú wù zhàn kě yǐ lín shí xiū xī dào yǔ tíng。','Ngoài đó nước ngập sâu quá nên xe công nghệ cũng không vào được, em cứ tạm nghỉ ở trạm dịch vụ cộng đồng đến khi tạnh mưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_05','V1011','阮明',5,'真的太感谢您了，我本来打算赶回去上晚自习，这下彻底赶不上啦。','zhēn de tài gǎn xiè nín le， wǒ běn lái dǎ suàn gǎn huí qù shàng wǎn zì xí， zhè xià chè dǐ gǎn bù shàng la。','Em cảm ơn chị nhiều lắm, lúc đầu em định chạy về kịp giờ tự học buổi tối mà giờ chắc chắn trễ mất rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_06','V1011','小吴',6,'我给你倒杯热水，你可以跟辅导员发消息说明下情况。','wǒ gěi nǐ dào bēi rè shuǐ， nǐ kě yǐ gēn fǔ dǎo yuán fā xiāo xī shuō míng xià qíng kuàng。','Chị rót cho em cốc nước nóng nhé, em nhắn tin báo tình hình cho thầy cô chủ nhiệm biết đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_07','V1011','阮明',7,'好，借您充电插座充会儿手机，等雨小一点我再想办法返校。','hǎo， jiè nín chōng diàn chā zuò chōng huì er shǒu jī， děng yǔ xiǎo yì diǎn wǒ zài xiǎng bàn fǎ fǎn xiào。','Vâng, em mượn ổ cắm sạc điện thoại một lát, đợi mưa nhỏ bớt em sẽ tìm cách quay lại trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_08','V1011','小吴',8,'安心休息，暴雨天道路不安全，千万不要强行涉水外出。','ān xīn xiū xī， bào yǔ tiān dào lù bù ān quán， qiān wàn bú yào qiáng xíng shè shuǐ wài chū。','Em cứ yên tâm nghỉ ngơi đi, trời mưa to đường sá không an toàn đâu, tuyệt đối đừng cố lội nước ra ngoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1012','SKC1','街边小吃食物中毒集体腹痛，拨打市场监管热线投诉',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1012','SIT1012','P1','twist','chinh_thuc',NULL,'餐饮食物中毒维权需要保留消费凭证、医院诊断单据，监管部门会现场抽检食材，属实可要求商家全额赔偿医药费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_01','V1012','阮明',1,'您好，我要举报街边小吃摊，吃完东西之后我和两个同学都腹痛腹泻。','nín hǎo， wǒ yào jǔ bào jiē biān xiǎo chī tān， chī wán dōng xī zhī hòu wǒ hé liǎng gè tóng xué dōu fù tòng fù xiè。','Xin chào, tôi muốn tố cáo một quầy đồ ăn vặt ven đường, sau khi ăn xong tôi và hai người bạn đều bị đau bụng, tiêu chảy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_02','V1012','接线员',2,'麻烦告知小吃摊具体地址、摊位名称，还有你们就餐的时间吧。','má fán gào zhī xiǎo chī tān jù tǐ dì zhǐ、 tān wèi míng chēng， hái yǒu nǐ men jiù cān de shí jiān ba。','Phiền anh cho biết địa chỉ cụ thể, tên quầy hàng, cùng thời gian các anh dùng bữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_03','V1012','阮明',3,'学校南门巷子里的无名炸串摊，今天傍晚六点左右我们一起消费的啊。','xué xiào nán mén xiàng zi lǐ de wú míng zhà chuàn tān， jīn tiān bàng wǎn liù diǎn zuǒ yòu wǒ men yì qǐ xiāo fèi de a。','Đó là quầy xiên que chiên không tên nằm trong con hẻm ở cổng nam trường, khoảng sáu giờ chiều nay chúng tôi cùng mua ở đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_04','V1012','接线员',4,'你们现在身体状况怎么样，有没有去医院开具诊断证明呢？','nǐ men xiàn zài shēn tǐ zhuàng kuàng zěn me yàng， yǒu méi yǒu qù yī yuàn kāi jù zhěn duàn zhèng míng ne？','Hiện tại tình trạng sức khỏe của các anh thế nào, đã đến bệnh viện xin giấy chẩn đoán chưa ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_05','V1012','阮明',5,'刚从社区诊所出来，医生判定是不洁食物引发的肠胃不适。','gāng cóng shè qū zhěn suǒ chū lái， yī shēng pàn dìng shì bù jié shí wù yǐn fā de cháng wèi bù shì。','Chúng tôi vừa từ phòng khám cộng đồng ra, bác sĩ chẩn đoán là do thức ăn không sạch gây rối loạn tiêu hóa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_06','V1012','接线员',6,'需要携带就诊单据、消费记录，工作日到辖区监管所现场登记。','xū yào xié dài jiù zhěn dān jù、 xiāo fèi jì lù， gōng zuò rì dào xiá qū jiān guǎn suǒ xiàn chǎng dēng jì。','Các anh cần mang theo hóa đơn khám bệnh và hóa đơn mua hàng, đến trực tiếp cơ quan quản lý thị trường khu vực vào ngày làm việc để đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_07','V1012','阮明',7,'我们下周才有空过去，这段时间摊位要是关门跑路怎么办？','wǒ men xià zhōu cái yǒu kòng guò qù， zhè duàn shí jiān tān wèi yào shì guān mén pǎo lù zěn me bàn？','Tuần sau chúng tôi mới có thời gian đến được, nếu trong lúc này quầy hàng đóng cửa bỏ trốn thì phải làm sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_08','V1012','接线员',8,'我们会立刻安排工作人员上门核查，暂扣摊位食材留存证据。','wǒ men huì lì kè ān pái gōng zuò rén yuán shàng mén hé chá， zàn kòu tān wèi shí cái liú cún zhèng jù。','Chúng tôi sẽ lập tức cử người đến kiểm tra tận nơi, tạm giữ nguyên liệu của quầy hàng để lưu làm chứng cứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1013','SKC1','居留许可卡片断裂损毁，出入境大厅申请临时通行纸质证明',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1013','SIT1013','P1','suon_se','chinh_thuc',NULL,'外国人居留许可损毁、丢失均无法单独出行，临时纸质通行证明仅限国内短期交通出行使用，不能替代正式居留卡。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_01','V1013','阮明',1,'您好，我的外国人居留许可不小心折断了，没办法正常使用，想办临时通行证明。','nín hǎo， wǒ de wài guó rén jū liú xǔ kě bù xiǎo xīn zhé duàn le， méi bàn fǎ zhèng cháng shǐ yòng， xiǎng bàn lín shí tōng xíng zhèng míng。','Xin chào, thẻ cư trú người nước ngoài của tôi không may bị gãy, không thể sử dụng bình thường được nữa, tôi muốn xin cấp giấy chứng nhận thông hành tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_02','V1013','刘柜员',2,'先出示你的护照，还有破损的居留卡，我先核验一下信息吧。','xiān chū shì nǐ de hù zhào， hái yǒu pò sǔn de jū liú kǎ， wǒ xiān hé yàn yī xià xìn xī ba。','Anh cho tôi xem hộ chiếu và tấm thẻ cư trú bị hỏng trước, để tôi kiểm tra thông tin đã.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_03','V1013','阮明',3,'卡片中间裂开，刷卡机识别不了，下周还要坐高铁外出办事呢。','kǎ piàn zhōng jiān liè kāi， shuā kǎ jī shí bié bù liǎo， xià zhōu hái yào zuò gāo tiě wài chū bàn shì ne。','Thẻ bị nứt ở giữa nên máy quẹt không nhận diện được, tuần sau tôi còn phải đi tàu cao tốc ra ngoài giải quyết công việc nữa.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_04','V1013','刘柜员',4,'破损居留卡属于失效证件，临时纸质证明有效期只有七天哦。','pò sǔn jū liú kǎ shǔ yú shī xiào zhèng jiàn， lín shí zhǐ zhì zhèng míng yǒu xiào qī zhǐ yǒu qī tiān ó。','Thẻ cư trú bị hỏng được xem là giấy tờ không còn hiệu lực, giấy chứng nhận tạm thời bằng giấy chỉ có hiệu lực bảy ngày thôi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_05','V1013','阮明',5,'七天足够我补办新卡了，请问办理需要额外准备什么材料吗？','qī tiān zú gòu wǒ bǔ bàn xīn kǎ le， qǐng wèn bàn lǐ xū yào é wài zhǔn bèi shén me cái liào ma？','Bảy ngày là đủ để tôi làm lại thẻ mới rồi, xin hỏi làm thủ tục này có cần chuẩn bị thêm giấy tờ gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_06','V1013','刘柜员',6,'准备一张一寸白底证件照，填写补办申请表，现场等待半小时就能取证。','zhǔn bèi yī zhāng yī cùn bái dǐ zhèng jiàn zhào， tián xiě bǔ bàn shēn qǐng biǎo， xiàn chǎng děng dài bàn xiǎo shí jiù néng qǔ zhèng。','Anh chuẩn bị một tấm ảnh thẻ cỡ 1 inch nền trắng, điền vào đơn xin cấp lại, chờ tại chỗ khoảng nửa tiếng là lấy được giấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_07','V1013','阮明',7,'还好今天带齐证件过来，不然临时出行肯定会被拦下来。','hái hǎo jīn tiān dài qí zhèng jiàn guò lái， bù rán lín shí chū xíng kěn dìng huì bèi lán xià lái。','May mà hôm nay tôi mang đầy đủ giấy tờ, không thì lúc đi ra ngoài đột xuất chắc chắn sẽ bị chặn lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_08','V1013','刘柜员',8,'拿好临时证明，这段时间出门一定要同时携带护照。','ná hǎo lín shí zhèng míng， zhè duàn shí jiān chū mén yí dìng yào tóng shí xié dài hù zhào。','Anh giữ kỹ giấy chứng nhận tạm thời này, trong thời gian này ra ngoài nhất định phải mang theo cả hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1014','SKC1','签证线上缴费扣款成功但系统未入账，联系出入境财务加急核对',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1014','SIT1014','P1','that_bai_nhe','chinh_thuc',NULL,'政务线上缴费存在银行、政务系统对账时差，窗口开具纸质临时凭证可临时规避审核拦截。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_01','V1014','阮明',1,'陈会计您好，我昨天线上续签签证缴费，银行卡已经扣款，系统却显示未缴费。','chén kuài jì nín hǎo， wǒ zuó tiān xiàn shàng xù qiān qiān zhèng jiǎo fèi， yín háng kǎ yǐ jīng kòu kuǎn， xì tǒng què xiǎn shì wèi jiǎo fèi。','Chào kế toán Trần, hôm qua tôi thanh toán phí gia hạn visa trực tuyến, thẻ ngân hàng đã bị trừ tiền nhưng hệ thống lại hiển thị chưa thanh toán.',NULL) ON CONFLICT DO NOTHING;
